def proverb(*pieces, qualifier=None):
    if not pieces:
        return []

    lines = [
        f"For want of a {a} the {b} was lost."
        for a, b in zip(pieces, pieces[1:])
    ]

    if qualifier:
        last = f"And all for the want of a {qualifier} {pieces[0]}."
    else:
        last = f"And all for the want of a {pieces[0]}."
    lines.append(last)

    return lines
